// Title: Add an external CSS link to Aspose.Cells HTML export with TableCssId class prefix in C#
// Common Searches: how to reference an external stylesheet in HTML generated by Aspose.Cells using C# | C# Aspose.Cells export workbook to HTML and add custom CSS link | insert <link> tag into Aspose.Cells HTML output for site‑wide styling | Aspose.Cells HtmlSaveOptions external CSS with prefixed TableCssId classes | modify generated HTML from Aspose.Cells to include styles.css in C#
// Tags: Aspose.Cells HTML export external CSS integration | C# insert stylesheet link into generated HTML | TableCssId class prefix styling with external CSS | HtmlSaveOptions custom link tag handling | site‑wide stylesheet for Aspose.Cells HTML output

using System;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, fills it with sample data, configures HtmlSaveOptions for HTML5, saves the workbook to a memory stream, reads the HTML string, injects a <link rel="stylesheet" href="styles.css"> tag after the <head> element (or at the start if <head> is missing), and writes the final HTML file, enabling site‑wide styling of the prefixed TableCssId classes.
class HtmlExportWithExternalCss
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add some sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Name");
            sheet.Cells["B1"].PutValue("Score");
            sheet.Cells["A2"].PutValue("Alice");
            sheet.Cells["B2"].PutValue(85);
            sheet.Cells["A3"].PutValue("Bob");
            sheet.Cells["B3"].PutValue(92);

            // Configure HTML save options
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
            // Use HTML5 for better compatibility
            htmlOptions.HtmlVersion = HtmlVersion.Html5;
            // Note: In newer Aspose.Cells versions, ExportCss and CssClassPrefix may be unavailable.
            // The default behavior embeds CSS; if external CSS is required, it can be handled manually.

            // Save the workbook to a memory stream as HTML
            using (MemoryStream htmlStream = new MemoryStream())
            {
                workbook.Save(htmlStream, htmlOptions);
                htmlStream.Position = 0;
                string htmlContent = new StreamReader(htmlStream).ReadToEnd();

                // Prepare the external stylesheet link tag
                string cssLinkTag = "<link rel=\"stylesheet\" type=\"text/css\" href=\"styles.css\" />\n";

                // Insert the link tag just after the opening <head> tag
                int headIndex = htmlContent.IndexOf("<head>", StringComparison.OrdinalIgnoreCase);
                if (headIndex != -1)
                {
                    headIndex += "<head>".Length;
                    htmlContent = htmlContent.Insert(headIndex, "\n    " + cssLinkTag);
                }
                else
                {
                    // Fallback: prepend the link tag at the very beginning if <head> is missing
                    htmlContent = cssLinkTag + htmlContent;
                }

                // Write the final HTML to a file
                string outputPath = "ExportedReport.html";
                File.WriteAllText(outputPath, htmlContent);
                Console.WriteLine($"HTML exported with external stylesheet linked to '{outputPath}'.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred during HTML export: " + ex.Message);
        }
    }
}
